import java.time.*;
import java.util.*;
import java.util.function.Supplier;

public class Main {
    static final class BlockException extends RuntimeException {
        BlockException(String rule) { super(rule); }
    }

    static final class MiniSentinel {
        private final int qpsLimit;
        private final Duration window;
        private final long slowMs;
        private final int slowThreshold;
        private final Map<String, Deque<Instant>> qps = new HashMap<>();
        private final Map<String, Integer> slowCount = new HashMap<>();
        private final Map<String, Instant> openUntil = new HashMap<>();

        MiniSentinel(int qpsLimit, Duration window, long slowMs, int slowThreshold) {
            this.qpsLimit = qpsLimit;
            this.window = window;
            this.slowMs = slowMs;
            this.slowThreshold = slowThreshold;
        }

        synchronized <T> T call(String resource, Supplier<T> business) {
            Instant now = Instant.now();
            // 熔断窗口打开时快速失败（模拟 DegradeSlot）
            Instant until = openUntil.get(resource);
            if (until != null && now.isBefore(until)) {
                throw new BlockException("degrade-open");
            }
            // 滑动窗口 QPS 统计（模拟 StatisticSlot + FlowSlot）
            Deque<Instant> hits = qps.computeIfAbsent(resource, key -> new ArrayDeque<>());
            while (!hits.isEmpty() && Duration.between(hits.peekFirst(), now).compareTo(window) > 0) {
                hits.removeFirst();
            }
            if (hits.size() >= qpsLimit) {
                throw new BlockException("flow-qps");
            }
            hits.addLast(now);

            long start = System.nanoTime();
            try {
                return business.get();
            } finally {
                long costMs = Duration.ofNanos(System.nanoTime() - start).toMillis();
                // 慢调用计数，达阈值后打开熔断窗口（模拟 DegradeSlot）
                if (costMs >= slowMs) {
                    int slow = slowCount.merge(resource, 1, Integer::sum);
                    if (slow >= slowThreshold) {
                        openUntil.put(resource, Instant.now().plusMillis(500));
                    }
                }
            }
        }
    }

    static String guarded(MiniSentinel sentinel, String resource, Supplier<String> supplier) {
        try {
            return "pass " + sentinel.call(resource, supplier);
        } catch (BlockException blocked) {
            return "blocked " + blocked.getMessage();
        }
    }

    public static void main(String[] args) throws Exception {
        MiniSentinel sentinel = new MiniSentinel(2, Duration.ofSeconds(1), 30, 2);
        // QPS=2 的流控：前两个通过，第三个被拦截
        System.out.println(guarded(sentinel, "query", () -> "q1"));
        System.out.println(guarded(sentinel, "query", () -> "q2"));
        System.out.println(guarded(sentinel, "query", () -> "q3"));

        Thread.sleep(1100); // 等窗口过期
        // 慢调用熔断：两次慢调用后窗口打开，第三次被熔断
        System.out.println(guarded(sentinel, "pay", () -> slow("p1")));
        System.out.println(guarded(sentinel, "pay", () -> slow("p2")));
        System.out.println(guarded(sentinel, "pay", () -> "p3"));
    }

    static String slow(String value) {
        try {
            Thread.sleep(40);
            return value;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return "interrupted";
        }
    }
}
